<script lang="ts">
 import{onMount}from'svelte';import{page}from'$app/state';import{beforeNavigate,goto}from'$app/navigation';import{request}from'./api';import{stageExport}from'./editor-handoff.mjs';import{Button}from'$lib/components/ui/button';import{ArrowLeft,X,Film,Clapperboard}from'@lucide/svelte';import{selectStudioProject}from'./navigation';
 let{user}:{user:any}=$props();let projects=$state<any[]>([]),project=$state(''),error=$state(''),sources=$state<any[]>([]),sourcesOpen=$state(false),busy=$state(false),frame=$state<HTMLIFrameElement>(),editorReady=$state(false),publishEnabled=$state(false),notice=$state('');
 onMount(()=>{void load();});async function load(){try{const [items,options]=await Promise.all([request('/projects'),request('/video-uploads/options').catch(()=>({enabled:false}))]);projects=items;publishEnabled=!!options.enabled&&!!user.verified;project=selectStudioProject(projects,page.url.searchParams.get('project'),localStorage.getItem(`videoflow.cloud.project.${user.id}`));}catch(e){error=(e as Error).message;}}
 let pendingFlush:{id:string;resolve:()=>void;reject:(e:Error)=>void;timer:ReturnType<typeof setTimeout>}|undefined;let navigationBusy=$state(false);let allowedNavigation='';
 function flushEditor(){if(!frame)return Promise.resolve(undefined);if(!editorReady)return Promise.reject(new Error('The editor is still loading. Wait before leaving.'));return new Promise<string>((resolve,reject)=>{const id=crypto.randomUUID();const timer=setTimeout(()=>{if(pendingFlush?.id!==id)return;frame?.contentWindow?.postMessage({type:'videoflow:editor:resume',requestId:id},page.url.origin);pendingFlush=undefined;reject(new Error('Saving took too long. Your editor remains open; try again.'));},10000);pendingFlush={id,resolve:()=>resolve(id),reject,timer};frame?.contentWindow?.postMessage({type:'videoflow:editor:flush',requestId:id},page.url.origin);});}
 async function leave(href:string,external=false){if(navigationBusy)return;navigationBusy=true;error='';const previousFrame=frame;let flushedId:string|undefined;try{flushedId=await flushEditor();allowedNavigation=href;if(external){window.location.assign(href);return;}await goto(href);const destination=new URL(href,page.url.origin);if(destination.pathname==='/studio/editor'){const id=destination.searchParams.get('project');if(id&&id!==project){localStorage.setItem(`videoflow.cloud.project.${user.id}`,id);editorReady=false;project=id;}}}catch(e){error=(e as Error).message;const id=pendingFlush?.id;if(id)frame?.contentWindow?.postMessage({type:'videoflow:editor:resume',requestId:id},page.url.origin);}finally{if(flushedId)previousFrame?.contentWindow?.postMessage({type:'videoflow:editor:resume',requestId:flushedId},page.url.origin);allowedNavigation='';navigationBusy=false;}}
 beforeNavigate(navigation=>{const href=navigation.to?.url.href;if(href&&href===allowedNavigation)return;if(!frame)return;navigation.cancel();if(href)void leave(href,navigation.willUnload);else error='Wait for the timeline to save before closing this tab.';});
 function choose(id:string){void leave(new URL(`/studio/editor?project=${encodeURIComponent(id)}`,page.url.origin).href);}

 async function openSources(){sourcesOpen=true;busy=true;error='';sources=[];try{const jobs=await request('/jobs');for(const job of jobs.filter((j:any)=>j.project_id===project&&j.status==='succeeded').slice(0,30)){try{const output=await request(`/jobs/${job.id}/output`);if(output.asset_id)sources.push({...output,label:job.prompt||job.id});}catch{}}}catch(e){error=(e as Error).message;}finally{busy=false;}}
 function receive(e:MessageEvent){if(e.origin!==page.url.origin||e.source!==frame?.contentWindow)return;if(e.data?.type==='videoflow:editor:flushed'){if(pendingFlush&&e.data.requestId===pendingFlush.id&&typeof e.data.ok==='boolean'){const pending=pendingFlush;clearTimeout(pending.timer);pendingFlush=undefined;if(e.data.ok)pending.resolve();else pending.reject(new Error(typeof e.data.error==='string'?e.data.error:'Unable to save the timeline.'));}return;}switch(e.data?.type){case'videoflow:editor:ready':editorReady=true;break;case'videoflow:editor:exit':void leave(new URL('/studio/dashboard',page.url.origin).href);break;case'videoflow:editor:storyboard':void leave(new URL(`/studio?project=${encodeURIComponent(project)}`,page.url.origin).href);break;case'videoflow:editor:generate':void leave(new URL(`/create?project=${encodeURIComponent(project)}`,page.url.origin).href);break;case'videoflow:editor:sources':void openSources();break;case'videoflow:editor:exported':try{if(!publishEnabled)throw new Error('Video uploads are not available. Download your export to keep a copy.');stageExport(user.id,e.data);void leave(new URL('/studio/upload?from=editor',page.url.origin).href);}catch(errorValue){error=(errorValue as Error).message;}break;case'videoflow:editor:publish':void leave(new URL('/studio/upload',page.url.origin).href);break;case'videoflow:editor:imported':notice='Source imported into project media. Drag it onto the timeline.';sourcesOpen=false;break;}}
 function importSource(asset:any){frame?.contentWindow?.postMessage({type:'videoflow:editor:import',asset:{id:asset.asset_id,name:asset.filename||'generated-video.mp4',type:asset.content_type||'video/mp4'}},page.url.origin);notice='Importing source…';}
</script>
<svelte:window onmessage={receive}/>
<div class="editor-page">{#if error}<div class="editor-error" role="alert">{error}<Button variant="ghost" onclick={load}>Try again</Button></div>{/if}{#if !project}<div class="editor-start"><Clapperboard class="size-9"/><h1>Your editing workspace</h1><p>Create a project to start editing videos, text, captions and audio.</p><Button href="/projects">Open projects</Button></div>{:else}<div class="editor-project-bar"><a href="/studio/dashboard" aria-label="Studio overview"><ArrowLeft size={16}/></a><label for="editor-project" class="sr-only">Editing project</label><select id="editor-project" value={project} disabled={navigationBusy} onchange={e=>{const id=e.currentTarget.value;e.currentTarget.value=project;choose(id);}}>{#each projects as item}<option value={item.id}>{item.name}</option>{/each}</select><span>Browser editor</span></div>{#key project}<iframe bind:this={frame} title="VideoFlow video editor powered by OpenCut" src={`/editor-app/index.html?${new URLSearchParams({project,owner:user.id,publish:publishEnabled?'1':'0'})}`} allow="clipboard-read; clipboard-write; fullscreen" onload={()=>error=''}></iframe>{/key}{#if notice}<div class="editor-toast" role="status">{notice}<button onclick={()=>notice=''} aria-label="Dismiss"><X size={14}/></button></div>{/if}{/if}
{#if sourcesOpen}<aside class="source-drawer" aria-label="Project video sources"><header><h2>Project sources</h2><Button variant="ghost" size="icon" onclick={()=>sourcesOpen=false} aria-label="Close sources"><X size={18}/></Button></header><p>Import a completed generated video, then drag it from Media onto your timeline. Local uploads can be imported directly in the editor.</p>{#if busy}<p role="status">Loading your sources…</p>{:else if !sources.length}<div class="source-empty"><Film size={30}/><p>No completed videos in this project yet.</p><Button href={`/create?project=${encodeURIComponent(project)}`}>Generate a video</Button></div>{:else}{#each sources as asset}<div class="source-row"><span>{asset.label}</span><Button disabled={!editorReady} variant="outline" onclick={()=>importSource(asset)}>Import</Button></div>{/each}{/if}</aside>{/if}</div>
<style>.editor-page{height:100%;min-height:0;position:relative;display:flex;flex-direction:column}.editor-project-bar{height:34px;display:flex;align-items:center;gap:14px;padding:0 16px;border-bottom:1px solid var(--border);flex-shrink:0}.editor-project-bar select{border:0!important;background:transparent!important;width:auto!important;height:28px!important;max-width:260px!important}.editor-project-bar>span{margin-left:auto;font-size:10px;color:var(--muted-foreground)}iframe{width:100%;height:100%;border:0;flex:1;min-height:0}.editor-start{display:grid;place-content:center;justify-items:center;gap:20px;height:100%;padding:32px;text-align:center}.editor-start p{color:var(--muted-foreground)}.editor-error{padding:12px;background:var(--destructive);color:white;font-size:13px}.source-drawer{position:absolute;right:16px;top:50px;width:min(400px,calc(100% - 32px));max-height:calc(100% - 80px);overflow:auto;background:var(--popover);border:1px solid var(--border);border-radius:12px;padding:20px;box-shadow:0 12px 40px #0005}.source-drawer header{display:flex;justify-content:space-between;align-items:center}.source-drawer h2{font-size:18px}.source-drawer p{font-size:12px;color:var(--muted-foreground);line-height:1.8;margin:15px 0}.source-row{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:15px 0;border-top:1px solid var(--border)}.source-row>span{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.source-empty{padding:20px 0;text-align:center}.source-empty :global(svg){margin:auto}.editor-toast{position:absolute;bottom:35px;left:50%;transform:translateX(-50%);display:flex;gap:16px;align-items:center;padding:12px 18px;background:var(--popover);border:1px solid var(--border);border-radius:8px;font-size:12px;max-width:90%}
</style>
